package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamLitBank2 {
  private const val T = "බෞද්ධ සාහිත්‍යය, ජාතක කතා හා නූතන අභියෝග"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "බෞද්ධ සාහිත්‍යය හා නූතන අභියෝග අදාළ කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("බෝසතාණන් වහන්සේ කුස කුමරු ලෙස ඉපදී ඉටු කළ උතුම් කාර්යය කුමක්ද?", "ප්‍රභාවතී දිනා ගැනීම හා පරාර්ථචර්යාව", "රටින් පලා යාම", "යුද්ධ කිරීම", "මසුරු වීම", "කුස කුමරු පරාර්ථචර්යාවෙන් දියුණු විය."),
    q("ජාතක කතාවල එන 'මහාසිලව ජාතකය' මගින් රජවරුන්ට හා පාලකයන්ට උගන්වන ප්‍රධාන පාඩම කුමක්ද?", "ධාර්මිකව හා දස රාජ ධර්මයෙන් රට පාලනය කිරීම", "යුද්ධ කිරීම", "බදු වැඩි කිරීම", "සතුන් මැරීම", "ධාර්මික පාලනය රජුගේ වගකීමයි."),
    q("සිංහල සාහිත්‍යයේ එන 'පූජාවලිය' ග්‍රන්ථය රචනා කළ බුද්ධපුත්ත හිමියන් ජීවත් වූ යුගය කුමක්ද?", "දඹදෙණි යුගය", "අනුරාධපුර යුගය", "පොළොන්නරු යුගය", "කෝට්ටේ යුගය", "දඹදෙණි යුගයේදී පූජාවලිය රචනා විය."),
    q("සද්ධර්මරත්නාවලියේ එන කතා පුවත්වලින් මිනිස් සජීවී ස්වභාවය පෙන්වන්නේ කෙසේද?", "පව් කිරීමෙන් ලබන දුකත් කුසල් කිරීමෙන් ලබන සතුටත් පැහැදිලි කරමින්", "කතාවලින් පමණක්", "යුද්ධ විස්තර කරමින්", "වෙළඳාම උගන්වමින්", "කර්ම විපාකය සද්ධර්මරත්නාවලියෙන් පෙන්වයි."),
    q("බුදුරදුන්ගේ චරිතය පාදක කර ගනිමින් ගුරුළුගෝමීන් විසින් රචිත 'අමාවතුර' ග්‍රන්ථය බෙදී ඇති පරිච්ඡේද (අධිකාර) ගණන කීයද?", "අධිකාර අටකි", "පහකි", "දහයකි", "විස්සකි", "අමාවතුර අධිකාර 8 කින් යුක්තය."),
    q("අමාවතුර ග්‍රන්ථයේ නම ලැබීමට හේතු වූ කරුණ කුමක්ද?", "මාරයා සහ කෙලෙස් දමනය කරන අමෘත වතුර බඳු දහම දෙසන බැවින්", "පොකුණක් අසල ලියූ බැවින්", "ජලය ගැන කතා කරන බැවින්", "රජුගේ නම වූ බැවින්", "අමෘත වතුර වැනි දහම දැක්වීමයි."),
    q("සිංහල කාව්‍ය සාහිත්‍යයේ 'හංස සංදේශය' රචනා කරන ලද්දේ කවුරුන් විසින්ද?", "වීදාගම මෛත්‍රෙය හිමි", "තොටගමුවේ රාහුල හිමි", "වැත්තෑවේ හිමි", "කෝට්ටේ පරාක්‍රමබාහු රජු", "වීදාගම හිමි හංස සංදේශය රචනා කළහ."),
    q("නූතන සමාජයේ මුහුණපාන ප්‍රධාන අභියෝගයක් වන 'පරිසර දූෂණය' මැඩපැවැත්වීමට බෞද්ධ ඉගැන්වීම්වලින් ලැබෙන මගපෙන්වීම කුමක්ද?", "ලෝභය පාලනය කරමින් ගස්වැල් රැකීම හා සම්පත් නාස්ති නොකිරීම", "ගස් සියල්ල කපා දැමීම", "කර්මාන්ත වැඩි කිරීම", "ඉවත දැමීම", "තෘෂ්ණාව පාලනය පරිසරය රකියි."),
    q("බෞද්ධ සාහිත්‍යයේ ජාතක කතාවලින් උගන්වන පාරමිතා ධර්ම අතර 'අධිට්ඨාන පාරමිතාව' යනු කුමක්ද?", "අරමුණින් නොසැලී ස්ථිර අධිෂ්ඨානයෙන් කටයුතු කිරීම", "ඉක්මනින් වෙනස් වීම", "බිය වීම", "අන් අයට දොස් කීම", "අධිෂ්ඨානයෙන් යුතුව අරමුණට යෑමයි."),
    q("බෝසතාණන් වහන්සේ විධුර පණ්ඩිත ලෙස ඉපදී පිරූ උතුම් පාරමිතාව කුමක්ද?", "ප්‍රඥා පාරමිතාව හා සත්‍යය", "දාන පාරමිතාව පමණි", "සීල පාරමිතාව පමණි", "විරිය පාරමිතාව පමණි", "විධුර ජාතකයේ ප්‍රඥාව ප්‍රකට වේ."),
    q("බුද්ධ ශාසනයේ චිරස්ථිතිය උදෙසා සාහිත්‍යය භාවිත වූ අයුරු පෙන්වන හොඳම නිදසුන කුමක්ද?", "ත්‍රිපිටකය හා අටුවා ග්‍රන්ථ ලේඛනගත කිරීම", "රජවරුන් සටන් කිරීම", "වෙළඳ ගිවිසුම්", "ගල් කැටයම් කිරීම", "ග්‍රන්ථාරූඪ කිරීම ශාසන ආරක්ෂාවට මුල් විය."),
    q("නූතන තරුණ පරපුර අතර මතුවන 'පවුල් සංස්ථාවේ බිඳවැටීම්' වළක්වා ගැනීමට බුදුදහම දෙන ප්‍රධාන අවවාදය කුමක්ද?", "අඹුසැමි විශ්වාසය, කෘතගුණී බව හා මෛත්‍රිය රැකීම", "වෙන් වී ජීවත් වීම", "නිතර ගැටුම් ඇති කර ගැනීම", "සමාජයෙන් ඈත් වීම", "විශ්වාසය පවුල් සමගිය රකියි."),
    q("ජාතක පොතේ එන 'මහාසුදස්සන ජාතකය' මගින් ජීවිතයේ කුමන ස්වභාවය උගන්වයිද?", "මහා මාලිගා හිමිව සිටියත් සියලු සංස්කාර අනිත්‍ය වන බව", "සැමදා ජීවත් විය හැකි බව", "ධනය සදාකාලික බව", "රජුන් නොමැති වන බව", "මහාසුදස්සන මාලිගය අစ අහිමි වී ගියේය."),
    q("බෞද්ධ සාහිත්‍යයේ එන 'වෙස්සන්තර ජාතක කතාව' අසන විට ජනතාව තුළ ඇතිවන ප්‍රධාන මනෝභාවය කුමක්ද?", "මහා කරුණාව, දානමය සිත හා පරිත්‍යාගශීලීබව", "කෝපය", "ඊර්ෂ්‍යාව", "බිය", "දාන පාරමිතාවේ උතුම් බව වැටහේ."),
    q("සිංහල ගද්‍ය සාහිත්‍යයේ සුවිශේෂී කෘතියක් වන 'සද්ධර්මරත්නාවලිය' රචනා වූයේ කවර යුගයකද?", "දඹදෙණි යුගයේදී", "අනුරාධපුර යුගයේදී", "පොළොන්නරු යුගයේදී", "මහනුවර යුගයේදී", "දඹදෙණි යුගයේ ධර්මසේන හිමි රචනා කළහ."),
    q("බුදුරදුන්ගේ ජීවිතය හා බෞද්ධ සංස්කෘතිය ප්‍රචලිත කිරීමේදී සාහිත්‍ය කෘති ඉටු කළ ප්‍රධාන මෙහෙය කුමක්ද?", "ජනතාවට ධර්මය පහසුවෙන් අවබෝධ කර ගැනීමට මඟ පෙන්වීම", "යුද්ධ උගන්වීම", "කාලය නාස්ති කිරීම", "බදු එකතු කිරීම", "සාහිත්‍යයෙන් ධර්මය ජනතාවට ළං විය."),
    q("නූතන ලෝකයේ මුහුණපාන ආර්ථික අර්බුදවලට මුහුණ දීමට බෞද්ධ ආර්ථික දර්ශනයේ ඇති ප්‍රායෝගික ක්‍රමය කුමක්ද?", "අප්‍රමාදය, අරපිරිමැස්ම හා ණය නැතිව ජීවත් වීම", "අධික ලෙස ණය ගැනීම", "සම්පත් නාස්ති කිරීම", "සූදු කෙළීම", "අරපිරිමැස්ම ආර්ථික අර්බුද නසයි."),
    q("ජාතක කතාවල එන 'කුස ජාතකය' මගින් ප්‍රේමයේ හා විවාහ ජීවිතයේ ඇතිවන අභියෝග ජය ගැනීමට උගන්වන පාඩම කුමක්ද?", "ඉවසීමෙන් හා කැපවීමෙන් අභියෝග ජය ගැනීම", "පලා යාම", "තරහ ගැනීම", "අන් අයට හිංසා කිරීම", "කුස කුමරු ඉවසීමෙන් සියල්ල දිනා ගත්තේය."),
    q("බෞද්ධ සාහිත්‍යයේ අඩංගු ජාතක කතා සංඛ්‍යාව කොපමණ වේද?", "පන්සිය පනස් ජාතක කතා (550)", "සියයක්", "දහසක්", "දෙසීයකි", "ජාතක පොතේ කතා 550 ක් ඇත."),
    q("නූතන සමාජයේ විද්‍යාත්මක දියුණුවත් සමඟ මිනිසා තුළ ඇතිවන මානසික අතෘප්තිය දුරු කිරීමට බුදුදහම පෙන්වන මාර්ගය කුමක්ද?", "භාවනාව, සතිපට්ඨානය හා සන්තුට්ඨිතාව", "වැඩිපුර ධනය සෙවීම", "අනුන් මර්දනය කිරීම", "සමාජයෙන් පලා යාම", "සිත දියුණු කිරීමෙන් මානසික සුවය ලැබේ.")
  )
}
